        "type": "object",
        "properties": {
          "customer_id": {
            "type": "string",
            "description": "The customer ID."
          },
          "promo_code": {
            "type": "string",
            "description": "The promotional code to validate."
          }
        },
        "required": [
          "customer_id",
          "promo_code"
        ]
      }
    },
    {
      "type": "function",
      "name": "add_to_cart",
      "description": "Add a product to the customer's cart. Creates a new cart item or increments an existing one. Enforces stock availability and the per-product quantity limit.",
      "parameters": {
        "type": "object",
        "properties": {
          "customer_id": {
            "type": "string",
            "description": "The customer ID."
          },
          "product_id": {
