      "parameters": {
        "type": "object",
        "properties": {
          "customer_id": {
            "type": "string",
            "description": "The customer ID."
          },
          "promo_code": {
            "type": "string",
            "description": "The promo code to remove."
          }
        },
        "required": [
          "customer_id",
          "promo_code"
        ]
      }
    },
